//! Runtime data: resolved enemy decision/effect families.
//!
//! Generated by the extraction pipeline from the pinned enemy-policy
//! catalogue plus an independent static walk of the eight area overlays.
//! Provenance, callback enumeration and instruction anchors live in
//! the extraction report; this module carries only semantic
//! ids, families and units.
//!
//! A record is either `resolved` with a decision plan and an effect plan, or
//! `blocked` with a typed blocker.  Nothing here falls back to another
//! record's policy: an unknown id, family or callback is an error.

const std = @import("std");

pub const schema = "suikoden-battle-enemy-effects/1";

pub const Base = struct {
    schema: []const u8,
    packet: []const u8,
    policy_sha256: []const u8,
    report: []const u8,
    report_sha256: []const u8,
    adapter: []const u8,
    adapter_sha256: []const u8,
    commit: []const u8,
};

pub const LibrarySlot = struct {
    slot: []const u8,
    name: []const u8,
    target: []const u8,
};

pub const Scan = struct {
    front_only: bool,
    draw_kind: []const u8,
    accept_at_least: u8,
};

pub const SecondDraw = struct {
    kind: []const u8,
    threshold: u8,
};

pub const Blocker = struct {
    code: []const u8,
    detail: []const u8,
};

pub const Camera = struct {
    descriptor: ?[]const u8 = null,
    wait: u8 = 0,
};

pub const Special = struct {
    kind: []const u8,
    target_required: bool,
    wait_frames: u8 = 0,
    descriptor: ?[]const u8 = null,
    callback: ?[]const u8 = null,
    script: ?[]const u8 = null,
    camera: ?Camera = null,
};

pub const PreGate = struct {
    draw_kind: []const u8,
    special_at_least: u8,
};

pub const RandomSlot = struct {
    divisor: []const u8,
    add: u8,
    validate: []const u8,
};

pub const Damage = struct {
    numerator: i32,
    denominator: i32,
    rounding: []const u8,
};

pub const Ordinary = struct {
    descriptor: ?[]const u8 = null,
    callback: ?[]const u8 = null,
    effect: ?Effect = null,
};

pub const Decision = struct {
    family: []const u8,
    admitted: bool,
    resolution: []const u8,
    scan: ?Scan = null,
    second_draw: ?SecondDraw = null,
    own_row_front_below: ?u8 = null,
    target_row_front_below: ?u8 = null,
    no_selection: ?[]const u8 = null,
    pre_gate: ?PreGate = null,
    random_slot: ?RandomSlot = null,
    special: ?Special = null,
    ordinary: ?Ordinary = null,
    blocker: ?Blocker = null,
    debug_formats: []const DebugFormat = &.{},
    printf_slot_calls: u32 = 0,
};

pub const DebugFormat = struct {
    address: u64,
    text: []const u8,
};

pub const Effect = struct {
    family: []const u8,
    resolution: []const u8 = "enemy_effects",
    damage: ?Damage = null,
    latch_mask: u8 = 0,
    target_script: ?[]const u8 = null,
    follow_up: ?[]const u8 = null,
    clears_callback: bool = true,
    blocker: ?Blocker = null,
};

pub const Record = struct {
    id: []const u8,
    name: []const u8,
    level: u8,
    hp: u16,
    decision: Decision,
    effect: Effect,
    status: []const u8,
};

pub const Resource = struct {
    id: []const u8,
    kind: []const u8,
    owner: []const u8,
    role: []const u8,
};

pub const Packet = struct {
    schema: []const u8,
    base: Base,
    library: []const LibrarySlot = &.{},
    decision_families: []const []const u8 = &.{},
    effect_families: []const []const u8 = &.{},
    records: []const Record,
    resources: []const Resource = &.{},

    pub fn validate(self: Packet) !void {
        if (!std.mem.eql(u8, self.schema, schema)) return error.UnsupportedEnemyEffectsPacket;
        if (!std.mem.eql(u8, self.base.schema, "suikoden-enemy-policy/1"))
            return error.UnsupportedBasePacket;
        try validHex(self.base.policy_sha256, 64);
        try validHex(self.base.report_sha256, 64);
        try validHex(self.base.adapter_sha256, 64);
        try validHex(self.base.commit, 40);
        if (self.records.len == 0 or self.records.len > 128) return error.InvalidEnemyRecords;
        var resolved: usize = 0;
        for (self.records, 0..) |*record, i| {
            try self.validateRecord(record);
            for (self.records[0..i]) |previous| {
                if (std.mem.eql(u8, previous.id, record.id)) return error.DuplicateEnemyRecord;
            }
            if (std.mem.eql(u8, record.status, "resolved")) resolved += 1;
        }
        if (resolved == 0) return error.InvalidEnemyRecords;
        for (self.resources, 0..) |resource, i| {
            if (resource.id.len == 0 or resource.kind.len == 0) return error.InvalidEnemyResource;
            for (self.resources[0..i]) |previous| {
                if (std.mem.eql(u8, previous.id, resource.id)) return error.InvalidEnemyResource;
            }
        }
    }

    fn validateRecord(self: Packet, record: *const Record) !void {
        _ = self;
        if (record.id.len == 0 or record.id.len > 64) return error.InvalidEnemyRecord;
        if (record.name.len == 0 or record.name.len > 32) return error.InvalidEnemyRecord;
        if (record.level == 0 or record.level > 99) return error.InvalidEnemyRecord;
        if (record.hp == 0) return error.InvalidEnemyRecord;
        const decision = record.decision;
        const resolved = std.mem.eql(u8, record.status, "resolved");
        if (resolved) {
            if (!decision.admitted) return error.ResolvedRecordNotAdmitted;
            if (decision.blocker != null) return error.ResolvedDecisionWithBlocker;
            if (!std.mem.eql(u8, record.effect.family, "blocked") and record.effect.blocker != null)
                return error.ResolvedEffectWithBlocker;
            if (std.mem.eql(u8, record.effect.family, "blocked"))
                return error.ResolvedRecordWithBlockedEffect;
        } else {
            if (!std.mem.eql(u8, record.status, "blocked")) return error.InvalidEnemyStatus;
            const blocker = decision.blocker orelse record.effect.blocker orelse return error.BlockedRecordWithoutBlocker;
            if (blocker.code.len == 0 or blocker.detail.len == 0)
                return error.BlockedRecordWithoutBlocker;
        }
        if (decision.scan) |scan| {
            if (scan.accept_at_least != 51) return error.InvalidEnemyScan;
            if (!knownDrawKind(scan.draw_kind)) return error.UnknownDrawKind;
        }
        if (decision.second_draw) |second| {
            if (!knownDrawKind(second.kind)) return error.UnknownDrawKind;
            if (second.threshold == 0 or second.threshold > 100) return error.InvalidSecondDraw;
        }
        if (decision.pre_gate) |gate| {
            if (!knownDrawKind(gate.draw_kind)) return error.UnknownDrawKind;
            if (gate.special_at_least == 0 or gate.special_at_least > 100)
                return error.InvalidPreGate;
        }
        if (decision.random_slot) |slot| {
            if (slot.add != 1) return error.InvalidRandomSlot;
            if (!std.mem.eql(u8, slot.divisor, "actor_count")) return error.InvalidRandomSlot;
        }
        if (decision.special) |special| {
            if (special.wait_frames > 120) return error.InvalidSpecialWait;
            if (!std.mem.eql(u8, special.kind, "script") and
                !std.mem.eql(u8, special.kind, "descriptor") and
                !std.mem.eql(u8, special.kind, "descriptor_callback"))
                return error.InvalidSpecialKind;
        }
        if (!std.mem.eql(u8, decision.family, "blocked") and
            !std.mem.eql(u8, decision.family, "ordinary") and
            !knownDecisionFamily(decision.family)) return error.UnknownDecisionFamily;
        if (!std.mem.eql(u8, record.effect.family, "blocked") and
            !knownEffectFamily(record.effect.family)) return error.UnknownEffectFamily;
        if (record.effect.damage) |damage| {
            if (damage.denominator <= 0) return error.InvalidEffectDamage;
            if (damage.numerator < 0) return error.InvalidEffectDamage;
            if (!std.mem.eql(u8, damage.rounding, "toward_zero")) return error.InvalidEffectDamage;
        } else if (!std.mem.eql(u8, record.effect.family, "blocked")) {
            return error.MissingEffectDamage;
        }
    }

    pub fn find(self: *const Packet, id: []const u8) ?*const Record {
        for (self.records) |*record| {
            if (std.mem.eql(u8, record.id, id)) return record;
        }
        return null;
    }
};

pub fn knownDrawKind(kind: []const u8) bool {
    return std.mem.eql(u8, kind, "percent_100") or
        std.mem.eql(u8, kind, "scale_100_32767") or
        std.mem.eql(u8, kind, "scale_100_32767_mod_100");
}

pub fn knownDecisionFamily(family: []const u8) bool {
    const families = [_][]const u8{
        "random_target",
        "target_then_script_chance",
        "target_then_special_chance",
        "own_row_special",
        "target_row_special",
        "always_special",
        "pre_scan_special",
        "own_front_rally",
        "blocked",
    };
    for (families) |known| if (std.mem.eql(u8, family, known)) return true;
    return false;
}

pub fn knownEffectFamily(family: []const u8) bool {
    const families = [_][]const u8{
        "ordinary",
        "target_script_only",
        "physical_result_once",
        "physical_result_half_once",
        "physical_result_double_once",
        "physical_result_once_latch",
        "blocked",
    };
    for (families) |known| if (std.mem.eql(u8, family, known)) return true;
    return false;
}

fn validHex(value: []const u8, length: usize) !void {
    if (value.len != length) return error.InvalidCataloguePin;
    for (value) |c| if (!std.ascii.isHex(c)) return error.InvalidCataloguePin;
}

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Packet) {
    const parsed = try std.json.parseFromSlice(Packet, allocator, bytes, .{
        .allocate = .alloc_always,
        .ignore_unknown_fields = true,
    });
    errdefer parsed.deinit();
    try parsed.value.validate();
    return parsed;
}
